<?php
require __DIR__ . '/../app/bootstrap.php';
require_admin();
require_once __DIR__ . '/../app/recurring_charges.php';
$user=current_user();
if($_SERVER['REQUEST_METHOD']!=='POST')sync_recurring_charges($pdo);
$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 try{
  $action=$_POST['action']??'';
  if($action==='save'){
   $old=trim($_POST['nombre_anterior']??'');$name=trim($_POST['nombre']??'');
   if($name===''||mb_strlen($name)>80)throw new RuntimeException('El nombre es obligatorio y no puede superar los 80 caracteres.');
   $active=isset($_POST['activo'])?1:0;
   $pdo->beginTransaction();
   if($old!==''){
    $q=$pdo->prepare('SELECT nombre FROM categorias_cargos WHERE nombre=? FOR UPDATE');$q->execute([$old]);if(!$q->fetchColumn())throw new RuntimeException('La categoría que intentas editar ya no existe.');
    if($old!==$name){$q=$pdo->prepare('SELECT COUNT(*) FROM categorias_cargos WHERE nombre=?');$q->execute([$name]);if((int)$q->fetchColumn())throw new RuntimeException('Ya existe una categoría con ese nombre.');
     $q=$pdo->prepare('UPDATE cargos SET tipo=? WHERE tipo=?');$q->execute([$name,$old]);
     $q=$pdo->prepare('UPDATE cargos_recurrentes SET tipo=? WHERE tipo=?');$q->execute([$name,$old]);
     $q=$pdo->prepare('UPDATE categorias_cargos SET nombre=?,activo=? WHERE nombre=?');$q->execute([$name,$active,$old]);
    }else{$q=$pdo->prepare('UPDATE categorias_cargos SET activo=? WHERE nombre=?');$q->execute([$active,$old]);}
   }else{
    $q=$pdo->prepare('SELECT COUNT(*) FROM categorias_cargos WHERE nombre=?');$q->execute([$name]);if((int)$q->fetchColumn())throw new RuntimeException('Ya existe una categoría con ese nombre.');
    $q=$pdo->prepare('INSERT INTO categorias_cargos(nombre,activo,orden) VALUES(?,?,(SELECT COALESCE(MAX(orden),0)+10 FROM (SELECT orden FROM categorias_cargos) x))');$q->execute([$name,$active]);
   }
   $pdo->commit();$ok='Categoría guardada correctamente.';
  }elseif($action==='toggle'){
   $name=trim($_POST['nombre']??'');$q=$pdo->prepare('UPDATE categorias_cargos SET activo=IF(activo=1,0,1) WHERE nombre=?');$q->execute([$name]);if(!$q->rowCount())throw new RuntimeException('No se ha encontrado la categoría.');$ok='Estado de la categoría actualizado. Los movimientos antiguos no se han borrado.';
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar la categoría. Comprueba que database.sql esté actualizado.';}
}
$editName=trim($_GET['editar']??'');$edit=null;if($editName!==''){$q=$pdo->prepare('SELECT * FROM categorias_cargos WHERE nombre=?');$q->execute([$editName]);$edit=$q->fetch()?:null;}
$rows=$pdo->query("SELECT c.*, (SELECT COUNT(*) FROM cargos x WHERE x.tipo=c.nombre) cargos_n, (SELECT COUNT(*) FROM cargos_recurrentes r WHERE r.tipo=c.nombre) recurrentes_n FROM categorias_cargos c ORDER BY c.activo DESC,c.orden,c.nombre")->fetchAll();
